// registerAddedProviders adds the ported catalogs to the generated ones, so every
// reader of GeneratedProviders and GeneratedModels (listing, lookup, --list-models,
// the model registry and the remote catalog refresh) sees them.
func init() {
	GeneratedModels = append(GeneratedModels, addedProviderModels...)
	added := slices.Concat(GeneratedProviders, addedProviderIDs)
	slices.Sort(added)
	GeneratedProviders = slices.Compact(added)
}
